"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Hearts of the vineyard valley', 'author': 'Signature original', 'genre': 'Second Chances', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "Nora Ellis hadn't meant to come back to the vineyard valley. The city had been fine — fine in the way a waiting room is fine. But the letter about the old house, and a handwritten letter tucked inside it, had pulled her home like a tide.\n\nHe was there — the boy from that summer, grown into a man with the same laugh. Time folded. Nora Ellis's heart, so carefully guarded, did something reckless: it hoped.\n\nher neighbor Mrs. Abernathy met her at the station with a hug that smelled of the vineyard valley: salt, wildflowers, fresh bread. 'You look like you need pie,' her neighbor Mrs. Abernathy said, which was her neighbor Mrs. Abernathy's diagnosis for everything, and usually right."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "her overbearing mother — the reason she'd left, the shadow over it all — was still there, in the past where it belonged. Nora Ellis felt it loosen its grip. the heart knows first, she thought. Maybe. Just maybe.\n\na handwritten letter turned out to be a map of sorts: a letter never sent, a promise never kept. Nora Ellis read it on the porch swing while the vineyard valley hummed around her, and cried the good kind of crying.\n\nThey talked until the shop closed, until the streetlights came on in the vineyard valley. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared."}, {'n': 3, 'title': 'Complications', 'text': "Of course it couldn't be simple. her overbearing mother reappeared — older, smoother, with apologies like gift wrap. 'I've changed,' her overbearing mother said, and for an hour Nora Ellis almost believed it.\n\nHer grandmother Rose's voice came back to her: 'The heart knows first, baby. The head just takes minutes.' Nora Ellis stopped running. She turned around and went to find him.\n\na handwritten letter sat on her dresser, accusing and comforting by turns. She picked it up and finally understood what it was: not a map to the past, but permission for the future."}, {'n': 4, 'title': 'The Choice', 'text': 'He laughed through tears, the same laugh, and the sunset did its thing, and the vineyard valley held its breath again. This time nobody interrupted. This time they stayed.\n\nher overbearing mother left town with the gift wrap and the almosts. Nora Ellis felt nothing but pity — and then not even that, because her arms were full of present tense.\n\na handwritten letter got a place of honor on the mantel — not as a relic, but as a reminder: that love lost can be love found, that the heart knows first, and that home was never a town at all.'}, {'n': 5, 'title': 'The Promise', 'text': "Late that night, on the shore, they stood where the boy and girl had stood. 'We made it,' he said. 'We were always going to,' she said, and believed it, the heart knowing first.\n\nThey danced on the porch to the mixtape — no, to a new playlist, because the past is a place to visit, not to live. Nora Ellis had learned that at last.\n\nHe proposed with a handwritten letter — fitting, her neighbor Mrs. Abernathy said, since it started everything. Nora Ellis said yes before he finished asking, because seventeen years is long enough to wait for a sentence."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "the heart knows first. In the vineyard valley, in the wildflowers, in the salt air, in every sunset: the whole story, still beginning, never ending.\n\nNora Ellis walks the shore most evenings, sometimes alone, sometimes with him, always with the vineyard valley around her like a held breath. The sunsets haven't changed. She has — into someone who stays.\n\nAnd when the children ask about a handwritten letter, Nora Ellis tells them: it was a map. Not to a place — to a person. To the bravest thing she ever did, which was to come home."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

